from pathlib import Path
import argparse,json,re,uuid,hashlib
from driver import ps,q
r=Path(__file__).resolve().parents[2];p=argparse.ArgumentParser();p.add_argument('stage',type=Path);p.add_argument('--focus-only',action='store_true');p.add_argument('--clip-only',action='store_true');a=p.parse_args();v=json.loads(a.stage.read_text());assert v['owner']=='preflight'and v['component']=='capabilityviewport'and v['selfContained']and re.fullmatch(r'DBMV-Isolated-preflight-capabilityviewport-[0-9a-f]{32}',v['guestFolder']);digest=hashlib.sha256((r/'docs/replica/source/capabilityviewport-cases.json').read_bytes()).hexdigest();identity=uuid.uuid4().hex;folder=('headless-focus-'if a.focus_only else'headless-extra-')+identity
prepare="if((Test-Path ($app+'\\capabilityviewport-cases.json')) -and (Get-FileHash ($app+'\\capabilityviewport-cases.json') -Algorithm SHA256).Hash-ne "+q(digest.upper())+"){Move-Item ($app+'\\capabilityviewport-cases.json') ($app+'\\cases-before-canonical-'+[guid]::NewGuid().ToString('N')+'.json')};if(!(Test-Path ($app+'\\capabilityviewport-cases.json'))){Invoke-WebRequest -UseBasicParsing 'http://10.211.55.2:8768/capabilityviewport-cases.json' -OutFile ($app+'\\capabilityviewport-cases.json')};if((Get-FileHash ($app+'\\capabilityviewport-cases.json') -Algorithm SHA256).Hash-ne "+q(digest.upper())+" ){throw 'Owned cases hash mismatch'};"
code="$app=Join-Path (Join-Path $env:TEMP "+q(v['guestFolder'])+") 'app';"+prepare+"$out=Join-Path $app "+q(folder)+";New-Item -ItemType Directory $out|Out-Null;$env:DBMV_HEADLESS='1';$env:DBMV_HEADLESS_SCALE='2';& ($app+'\\ReplicaProbe.exe') '--capabilityviewport' ($app+'\\capabilityviewport-cases.json') $out '--extra-only' "+("'--focus-only' "+("'--clip-only'"if a.clip_only else'')if a.focus_only else'')+";if($LASTEXITCODE-ne 0){throw 'Viewport new headless input failed'};Get-Content -Raw ($out+'\\"+("capabilityviewport-focus-headless.json"if a.focus_only else"capabilityviewport-extra-headless.json")+"');"
data=ps(code,timeout=60);raw=data[data.index('{'):];value=json.loads(raw);out=r/'docs/replica/source/capabilityviewport-windows-headless';out.mkdir(exist_ok=True);(out/(identity+'.json')).write_text(json.dumps({'stage':str(a.stage),'guestOutput':folder,'headless':True,'scale':2,'result':value},indent=2)+'\n');print('Windows headless new states',len(value['states']),'output',out/(identity+'.json'))
